// #/bordo/<section>: the onboard cockpit (14 panels) mounted natively inside the shell.
// Same document, same Moon stage, same navigation: no iframe, no page change, CSP untouched.
// Single sources: the frame markup is cockpit.html's own .app subtree and the styles are cockpit.css,
// scoped to .cockpit-embed with @scope so they cannot leak into the shell. The board code is
// onboard/cockpit.js (mount/unmount); its synthetic-vs-real site boundary is unchanged.
// Source of truth: this .ts file. bordo.js is generated by `npm --prefix web run build:ts`.
import { bordoURL } from "../../ds/router.js";
/** Classic scripts of cockpit.html, in its order (they share globals: OnboardModel, OnboardApi, ...). */
export const COCKPIT_SCRIPTS = ["sim.js", "request.js", "model.js", "nav.js", "live.js", "features.js", "config.js", "api.js", "cockpit.js"];
const BASE = "onboard/";
let ready = null;
/** Rewrites cockpit.css for embedding: page-level rules apply to the wrapper, everything is scoped. */
export function scopeCockpitCSS(css, scope = ".cockpit-embed") {
    const body = css
        .replace(/(^|[},]\s*):root\s*(?=[{,])/g, "$1:scope ")
        .replace(/(^|[},]\s*)html\s*,\s*body\s*(?=\{)/g, "$1:scope ")
        .replace(/(^|[},]\s*)body\s*(?=\{)/g, "$1:scope ");
    return `@scope (${scope}) {\n${body}\n}`;
}
function loadScript(src) {
    if (document.querySelector(`script[data-cockpit="${src}"]`))
        return Promise.resolve();
    return new Promise((resolve, reject) => {
        const s = document.createElement("script");
        s.src = BASE + src;
        s.async = false;
        s.dataset.cockpit = src;
        s.onload = () => resolve();
        s.onerror = () => reject(new Error("COCKPIT_SCRIPT_UNAVAILABLE: " + src));
        document.head.append(s);
    });
}
async function prepare() {
    const [htmlRes, cssRes] = await Promise.all([fetch(BASE + "cockpit.html"), fetch(BASE + "cockpit.css")]);
    if (!htmlRes.ok || !cssRes.ok)
        throw new Error("COCKPIT_ASSETS_UNAVAILABLE");
    const doc = new DOMParser().parseFromString(await htmlRes.text(), "text/html"); // scripts in it never run
    const frame = [doc.querySelector(".app"), doc.getElementById("fab")].filter((n) => !!n);
    if (!frame.length)
        throw new Error("COCKPIT_FRAME_MISSING");
    const sheet = new CSSStyleSheet();
    sheet.replaceSync(scopeCockpitCSS(await cssRes.text()));
    document.adoptedStyleSheets = [...document.adoptedStyleSheets, sheet];
    window.OnboardCockpitDeferred = true;
    for (const src of COCKPIT_SCRIPTS)
        await loadScript(src);
    if (!window.OnboardCockpit)
        throw new Error("COCKPIT_API_MISSING");
    return { frame };
}
/** Links in cockpit.html are relative to onboard/; inside the shell they are relative to web/. */
function rebase(root) {
    root.querySelectorAll("a[href^='../']").forEach(a => a.setAttribute("href", a.getAttribute("href").slice(3)));
}
export async function render(outlet, ctx) {
    // Browsers without CSS @scope keep the standalone board page (same code, same routes).
    if (typeof globalThis.CSSScopeRule === "undefined" || !("adoptedStyleSheets" in document)) {
        location.replace(bordoURL("onboard/cockpit.html", ctx.parts, ctx.query));
        return;
    }
    let frame;
    try {
        ({ frame } = await (ready ??= prepare()));
    }
    catch (e) {
        ready = null;
        const p = document.createElement("section");
        p.className = "glass card";
        const h = document.createElement("h1");
        h.className = "title-l";
        h.dataset.routeTitle = "";
        h.textContent = "Painel de bordo";
        const t = document.createElement("p");
        t.className = "t2";
        t.setAttribute("role", "alert");
        t.textContent = "O painel de bordo não carregou (" + e.message + "). ";
        const a = document.createElement("a");
        a.href = bordoURL("onboard/cockpit.html", ctx.parts, ctx.query);
        a.textContent = "Abrir a página do painel";
        t.append(a);
        p.append(h, t);
        outlet.replaceChildren(p);
        return;
    }
    const wrap = document.createElement("div");
    wrap.className = "cockpit-embed";
    for (const n of frame)
        wrap.append(document.importNode(n, true));
    rebase(wrap);
    wrap.querySelector(".side .brand")?.remove(); // the shell header already links home
    wrap.querySelector("#topnav")?.remove(); // one primary navigation: the shell's
    wrap.querySelector("#page-title")?.setAttribute("data-route-title", "");
    outlet.replaceChildren(wrap);
    const site = ctx.query.site;
    const board = window.OnboardCockpit.mount({ root: wrap, embedded: true });
    return {
        // A section change (#/bordo/energia -> #/bordo/janelas) is applied in place; a site change remounts.
        update: next => { if (next.query.site !== site)
            return false; board.update(); return true; },
        dispose: () => board.unmount(),
    };
}
